const { NODEJS } = require('../../constants').OPTIONS
const { readProject } = require('../../projectReader')
const { merge } = require('../../merge')

module.exports = class CjsTemplate extends require('../../plugin') {

  static help() {
    return 'CommonJS-compatible Node.js project'
  }

  requires() {
    return [ NODEJS ]
  }

  async run() {
    const project = readProject()
    const { configFile } = project
    await merge(__dirname, 'files/package.json.hbs').into(configFile, { with: project, forceOverwrite: true })
  }

}
